contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address who, uint amount) public payable {
        require(who != address(0), "zero address");
        require(address(this).balance >= amount, "not enough balance");

        uint before = c.balances(who);
        uint minDeposit = c.MinDeposit();

        c.Deposit{value: amount}();

        uint afterBal = c.balances(who);

        if (msg.sender == who) {
            if (amount > minDeposit) {
                assert(afterBal == before + amount);
            } else {
                assert(afterBal == before);
            }
        } else {
            assert(afterBal == before);
        }
    }

    receive() external payable {}
}

